using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.LoyaltyDiscount;

public static class DiscountFixture
{
    public static int ExpectedTotalFrom(int originalSubtotalCents, LoyaltyTier loyaltyTier)
    {
        var baseRate = loyaltyTier switch
        {
            LoyaltyTier.Green => 5,
            LoyaltyTier.Gold => 7,
            LoyaltyTier.Platinum => 9,
            _ => throw new ArgumentOutOfRangeException(nameof(loyaltyTier), loyaltyTier, "Unknown loyalty tier."),
        };

        var bonus = originalSubtotalCents >= 20_000 ? 3 : originalSubtotalCents >= 5_000 ? 1 : 0;
        var effectiveRate = Math.Min(baseRate + bonus, 10);

        return originalSubtotalCents - (int)((long)originalSubtotalCents * effectiveRate / 100);
    }
}

